mapper.insert:
INSERT INTO g_cmnty_bbs
(
	  bbs_ttl
	, bbs_cn
	, notice_yn
	, inq_cnt
	, frst_crt_id
	, frst_crt_dt
	, is_secret
) VALUES
(
	  #{bbsTtl}
	, #{bbsCn}
	, #{noticeYn}
	, #{inqCnt}
	, #{frstCrtId}
	, NOW()
	, #{isSecret}
)

mapper.select:
SELECT COUNT(*) FROM ( SELECT a.bbs_id , a.bbs_ttl , a.bbs_cn , a.use_yn , a.notice_yn , IFNULL(a.inq_cnt, 0) as inq_cnt , a.frst_crt_id , a.frst_crt_dt , a.last_mdfcn_id , a.last_mdfcn_dt , b.user_name , (select min(authority) from op_user_role where user_id = a.frst_crt_id) as authority , CASE WHEN c.locgov_code IS NOT NULL THEN c.locgov_nm ELSE '' END AS locgov_nm ,CASE WHEN c.locgov_code IS NOT NULL THEN c.upper_locgov_nm ELSE '' END AS upper_locgov_nm FROM g_cmnty_bbs AS a LEFT JOIN op_manager AS b on a.frst_crt_id = b.user_id LEFT JOIN g_locgov AS c on c.locgov_code = b.locgov_code
AND c.locgov_code = #{locgovCode}
AND DATE_FORMAT(a.frst_crt_dt, '%Y%m%d') BETWEEN #{startDt} AND #{endDt}
AND a.frst_crt_id in (select user_id from op_user_role where authority in ('ROLE_ADMIN_1', 'ROLE_ADMIN_2'))
AND a.frst_crt_id in (select user_id from op_user_role where authority in ('ROLE_ADMIN_3', 'ROLE_ADMIN_4'))
AND a.frst_crt_id in (select user_id from op_user_role where authority in ('ROLE_ADMIN_5', 'ROLE_ADMIN_6', 'ROLE_ADMIN_10'))
AND bbs_ttl LIKE CONCAT('%', #{query}, '%')
AND b.user_name = #{query}
AND ( bbs_ttl LIKE CONCAT('%', #{query}, '%') OR b.user_name = #{query} )
AND a.use_yn = 'Y'
)

mapper.update:
update g_cmnty_bbs
set inq_cnt = IFNULL(inq_cnt, 0) +1
where bbs_id = #{bbsId}

UPDATE g_cmnty_bbs
SET use_yn = 'N'
	, last_mdfcn_id = #{frstCrtId}
	, last_mdfcn_dt = NOW()
WHERE bbs_id = #{bbsId}

